import pandas as pd
import pytest
from PySide6.QtWidgets import QMessageBox

from piggy_bank import etica
from piggy_bank.etica import COL_DATA, COL_MINUS, COL_PLUS, COL_DESCR, COL_BL, COL_INV

# The *_rc.py modules are generated by `./driver.sh -b`
pytest.importorskip('piggy_bank.ui.main_window_rc', reason='UI not built, run ./driver.sh -b')

from piggy_bank import main_window  # noqa: E402

# No Saturdays: the weekday histogram treats them as an error
ROWS = [('2025-01-02', -10.0, None, 'PIZZA'), ('2025-01-03', None, 100.0, 'SALARY')]


class FakeDialogs:
    """Stands in for QFileDialog and QMessageBox, returning canned answers and recording messages."""
    StandardButton = QMessageBox.StandardButton

    def __init__(self):
        self.path = ''
        self.answer = QMessageBox.StandardButton.Yes
        self.messages = []

    def getOpenFileName(self, *args, **kwargs):
        return self.path, ''

    def getSaveFileName(self, *args, **kwargs):
        return self.path, ''

    def question(self, *args, **kwargs):
        self.messages.append(('question', args[2]))
        return self.answer

    def critical(self, *args, **kwargs):
        self.messages.append(('critical', args[2]))

    def warning(self, *args, **kwargs):
        self.messages.append(('warning', args[2]))


@pytest.fixture
def dialogs(monkeypatch):
    fake = FakeDialogs()
    monkeypatch.setattr(main_window, 'QFileDialog', fake)
    monkeypatch.setattr(main_window, 'QMessageBox', fake)
    return fake


@pytest.fixture
def downloads(tmp_path_factory):
    """A folder outside DATA_DIR, where files to import come from."""
    return tmp_path_factory.mktemp('downloads')


@pytest.fixture
def window(qtbot, write_csv, dialogs):
    write_csv('estrattocontoitalia-2025.csv', ROWS)
    w = main_window.MainWindow()
    qtbot.addWidget(w)
    return w


def column(w, name) -> list:
    table = w.ui_ledger.qtw_ledger
    col = next(c for c in range(table.columnCount()) if table.horizontalHeaderItem(c).text() == name)
    return sorted(table.item(r, col).text() for r in range(table.rowCount()))


def fake_xls(monkeypatch, rows):
    df = pd.DataFrame(rows, columns=[COL_DATA, COL_MINUS, COL_PLUS, COL_DESCR])
    monkeypatch.setattr(etica.pd, 'read_excel', lambda path: df.copy())


def visible_descriptions(w) -> list:
    table = w.ui_ledger.qtw_ledger
    col = next(c for c in range(table.columnCount()) if table.horizontalHeaderItem(c).text() == COL_DESCR)
    return sorted(table.item(r, col).text() for r in range(table.rowCount()) if not table.isRowHidden(r))


class TestInvestmentColumn:

    @pytest.fixture
    def window(self, qtbot, write_csv, dialogs):
        write_csv('a.csv', ROWS + [('2025-01-06', -50.0, None, 'SOTTOSCRIZIONE FONDI')])
        w = main_window.MainWindow()
        qtbot.addWidget(w)
        return w

    def test_shown_like_blacklist(self, window):
        assert column(window, COL_INV) == ['0', '0', '1']
        assert column(window, COL_BL) == ['0', '0', '0']

    @pytest.mark.parametrize('mode, expected', [('all', ['PIZZA', 'SALARY', 'SOTTOSCRIZIONE FONDI']),
                                                ('force', ['SOTTOSCRIZIONE FONDI']),
                                                ('veto', ['PIZZA', 'SALARY'])])
    def test_radios_filter_on_column(self, window, mode, expected):
        getattr(window.ft, f'qrb_inv_{mode}').setChecked(True)
        window._apply_filters()

        assert visible_descriptions(window) == expected


class TestImportData:

    def test_adds_rows_and_converts(self, window, dialogs, downloads, data_dir, monkeypatch):
        fake_xls(monkeypatch, [('2025-01-06', -5.0, None, 'BREAD')])
        src = downloads / 'estrattocontoitalia-2026.xls'
        src.write_bytes(b'xls')
        dialogs.path = str(src)

        window.qa_import_data.trigger()

        assert column(window, COL_DESCR) == ['BREAD', 'PIZZA', 'SALARY']
        assert (data_dir / 'estrattocontoitalia-2026.csv').exists()
        assert not (data_dir / 'estrattocontoitalia-2026.xls').exists()
        assert src.exists()  # the original is copied, not moved
        assert dialogs.messages == []

    def test_cancelled_changes_nothing(self, window, dialogs, data_dir):
        before = sorted(p.name for p in data_dir.iterdir())

        window.qa_import_data.trigger()

        assert sorted(p.name for p in data_dir.iterdir()) == before
        assert column(window, COL_DESCR) == ['PIZZA', 'SALARY']

    def test_existing_statement_needs_confirmation(self, window, dialogs, downloads, data_dir, monkeypatch):
        fake_xls(monkeypatch, [('2025-01-06', -5.0, None, 'BREAD')])
        src = downloads / 'estrattocontoitalia-2025.xls'
        src.write_bytes(b'xls')
        dialogs.path = str(src)
        dialogs.answer = QMessageBox.StandardButton.No

        window.qa_import_data.trigger()

        assert dialogs.messages[0][0] == 'question'
        assert column(window, COL_DESCR) == ['PIZZA', 'SALARY']
        assert not (data_dir / 'estrattocontoitalia-2025.xls').exists()

    def test_existing_statement_replaced_when_confirmed(self, window, dialogs, downloads, data_dir, monkeypatch):
        # e.g. a newer export of the current year, which is a superset of the previous one
        fake_xls(monkeypatch, ROWS + [('2025-01-06', -5.0, None, 'BREAD')])
        src = downloads / 'estrattocontoitalia-2025.xls'
        src.write_bytes(b'xls')
        dialogs.path = str(src)

        window.qa_import_data.trigger()

        assert column(window, COL_DESCR) == ['BREAD', 'PIZZA', 'SALARY']

    def test_unreadable_xls_rolls_back(self, window, dialogs, downloads, data_dir, monkeypatch):
        def broken(path):
            raise ValueError('not an excel file')
        monkeypatch.setattr(etica.pd, 'read_excel', broken)
        src = downloads / 'garbage.xls'
        src.write_bytes(b'garbage')
        dialogs.path = str(src)

        window.qa_import_data.trigger()

        assert dialogs.messages[0][0] == 'critical'
        assert not (data_dir / 'garbage.xls').exists()
        assert column(window, COL_DESCR) == ['PIZZA', 'SALARY']


class TestImportBlacklist:

    def test_overwrites_and_refreshes(self, window, dialogs, downloads, data_dir, write_csv):
        write_csv('blacklist.csv', [(None, None, None, 'SALARY')])
        window._reload_data()
        assert column(window, COL_BL) == ['0', '1']

        src = downloads / 'my-blacklist.csv'
        pd.DataFrame([('2025-01-02', -10.0, None, 'pizza night')],
                     columns=[COL_DATA, COL_MINUS, COL_PLUS, COL_DESCR]).to_csv(src, index=False)
        dialogs.path = str(src)

        window.qa_import_blacklist.trigger()

        assert (data_dir / 'blacklist.csv').read_text() == src.read_text()
        assert column(window, COL_BL) == ['0', '1']
        assert dialogs.messages == []

    # Both rows share a date, so the OLS fit is degenerate
    @pytest.mark.filterwarnings('ignore::numpy.exceptions.RankWarning')
    def test_invalid_blacklist_restores_previous(self, qtbot, dialogs, downloads, data_dir, write_csv):
        write_csv('a.csv', [('2025-01-02', -9.0, None, 'SHOP A'), ('2025-01-02', -9.0, None, 'SHOP B')])
        previous = write_csv('blacklist.csv', [(None, None, None, 'SHOP A')]).read_text()
        w = main_window.MainWindow()
        qtbot.addWidget(w)

        # Matches both rows -> load_data() raises
        src = downloads / 'ambiguous.csv'
        pd.DataFrame([('2025-01-02', -9.0, None, None)],
                     columns=[COL_DATA, COL_MINUS, COL_PLUS, COL_DESCR]).to_csv(src, index=False)
        dialogs.path = str(src)

        w.qa_import_blacklist.trigger()

        assert dialogs.messages[0][0] == 'critical'
        assert (data_dir / 'blacklist.csv').read_text() == previous
        assert column(w, COL_BL) == ['0', '1']


class TestExportData:

    def test_copies_merged_csv(self, window, dialogs, downloads, data_dir):
        dst = downloads / 'export.csv'
        dialogs.path = str(dst)

        window.qa_export_data.trigger()

        assert dst.read_text() == (data_dir / 'merged.csv').read_text()

    def test_cancelled_writes_nothing(self, window, dialogs, downloads):
        window.qa_export_data.trigger()

        assert list(downloads.iterdir()) == []
